package keymap

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// Generated files, relative to the repository root. tools/gen-keymaps writes them;
// the tests check they match shared/keymaps.json.
const (
	CHeaderPath = "firmware/main/keymaps.h"
	TSPath      = "web/src/lib/layouts.gen.ts"
)

func cIdent(id string) string { return "KM_" + strings.ToUpper(strings.ReplaceAll(id, "-", "_")) }

// CHeader renders the firmware table: per layout, every typeable character sorted
// by code point (for bsearch) with one or two keystrokes.
func CHeader() []byte {
	var b bytes.Buffer
	b.WriteString(`// Generated by tools/gen-keymaps from shared/keymaps.json. Do not edit.
#pragma once
#include <stdint.h>

// One character: keystroke (m0, k0), then (m1, k1) unless k1 is 0 (dead key + letter or space).
typedef struct {
    uint16_t ch;
    uint8_t m0, k0, m1, k1;
} km_char_t;

typedef struct {
    const char *id;
    const km_char_t *chars; // sorted by ch
    uint16_t n;
} km_layout_t;
`)
	for _, l := range layouts {
		fmt.Fprintf(&b, "\n// %s (xkb %s)\nstatic const km_char_t %s[] = {", l.Name, l.XKB, cIdent(l.ID))
		for i, r := range l.Runes() {
			if i%4 == 0 {
				b.WriteString("\n   ")
			}
			s := l.chars[r]
			var m1, k1 uint8
			if len(s) > 1 {
				m1, k1 = s[1].Mods, s[1].Key
			}
			fmt.Fprintf(&b, " {0x%04X, 0x%02X, 0x%02X, 0x%02X, 0x%02X},", r, s[0].Mods, s[0].Key, m1, k1)
		}
		b.WriteString("\n};\n")
	}
	b.WriteString("\n// The first one is the fallback for unknown ids.\nstatic const km_layout_t KEYMAPS[] = {\n")
	for _, l := range layouts {
		id := cIdent(l.ID)
		fmt.Fprintf(&b, "    {\"%s\", %s, sizeof(%s) / sizeof(%s[0])},\n", l.ID, id, id, id)
	}
	b.WriteString("};\n#define KEYMAP_COUNT (sizeof(KEYMAPS) / sizeof(KEYMAPS[0]))\n")
	return b.Bytes()
}

func jsString(s string) string {
	var b bytes.Buffer
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(s)
	return strings.TrimSpace(b.String())
}

// TS renders the configurator's copy: layout ids and names, and what each can type.
func TS() []byte {
	var b bytes.Buffer
	b.WriteString("// Generated by tools/gen-keymaps from shared/keymaps.json. Do not edit.\n\nexport const LAYOUTS = [\n")
	for _, l := range layouts {
		fmt.Fprintf(&b, "  { id: %s, name: %s, xkb: %s },\n", jsString(l.ID), jsString(l.Name), jsString(l.XKB))
	}
	b.WriteString("] as const\n\nexport type LayoutId = (typeof LAYOUTS)[number]['id']\n\n")
	b.WriteString("// Characters each layout can type (newline and tab work everywhere).\nexport const LAYOUT_CHARS: Record<LayoutId, string> = {\n")
	for _, l := range layouts {
		var s strings.Builder
		for _, r := range l.Runes() {
			if r >= 0x20 {
				s.WriteRune(r)
			}
		}
		key := l.ID
		if strings.Contains(key, "-") {
			key = jsString(key)
		}
		fmt.Fprintf(&b, "  %s: %s,\n", key, jsString(s.String()))
	}
	b.WriteString("}\n")
	return b.Bytes()
}
